import React from 'react';

import { MeterBarSegment } from '../../../shared/components/meter-bar-segment/MeterBarSegment.js';
import { getSegmentWidth } from '../../../shared/functions/get-segment-width.js';
import { useMeterBarChartData } from '../../context/MeterBarChartDataContext.js';
import { useSegmentHandlers } from '../../hooks/useSegmentHandlers.js';

export const MeterBarChartSegment = () => {
  const { color, value, min, max, width } = useMeterBarChartData();
  const {
    handleSegmentMouseClick,
    handleSegmentMouseEnter,
    handleSegmentMouseLeave,
    handleSegmentMouseMove,
  } = useSegmentHandlers();

  const segmentWidth = getSegmentWidth(value, min, max, width);

  return (
    <MeterBarSegment
      color={color}
      width={segmentWidth}
      onClickAction={handleSegmentMouseClick}
      onMouseEnterAction={handleSegmentMouseEnter}
      onMouseLeaveAction={handleSegmentMouseLeave}
      onMouseMoveAction={handleSegmentMouseMove}
    />
  );
};

MeterBarChartSegment['displayName'] = 'MeterBarChartSegment';
